## 3️⃣ Map component / setup file (plain TS, works in React, Svelte, vanilla, etc.)

Below is a **stand-alone TypeScript module** (`src/map.ts`) that you can import from any UI framework.  
If you’re using React, just call `initMap(containerEl)` inside a `useEffect`; for vanilla you can call it after the DOM is ready.

```ts
// src/map.ts
import * as maplibregl from 'maplibregl';               // ← namespace import (no default export)
import { setWorkerUrl } from 'maplibre-gl';             // named export for the worker helper
import 'maplibre-gl/dist/maplibre-gl.css';              // ← bring in the default stylesheet

// 👉 Vite-specific import that resolves to the worker file URL at build time
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';

// ---------------------------------------------------------------------------
// 1️⃣ Tell MapLibre where the WebWorker lives (required for any bundler build)
// ---------------------------------------------------------------------------
setWorkerUrl(workerUrl);

// ---------------------------------------------------------------------------
// 2️⃣ Optional: resolve missing style images at runtime (v6 replaces the old
//    `styleimagemissing` event).  If you never reference unknown icons you can
//    skip this block.
// ---------------------------------------------------------------------------
maplibregl.setMissingStyleImageResolver(async (id: string) => {
  // Example: generate a simple 16×16 red square on-the-fly
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 16;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = 'red';
  ctx.fillRect(0, 0, 16, 16);
  const img = new Image();
  img.src = canvas.toDataURL();

  // Wait for the image to load (MapLibre expects the image to be ready)
  await new Promise((resolve) => (img.onload = resolve));

  // Register the image with the map – this resolves the pending request.
  // `map` is not yet defined here, so we store the image for later use.
  // The resolver is called *after* the map instance exists, so we can safely
  // add the image directly.
  map.addImage(id, img);
});

// ---------------------------------------------------------------------------
// 3️⃣ Create the map
// ---------------------------------------------------------------------------
export function initMap(container: HTMLElement | string) {
  const map = new maplibregl.Map({
    container,                     // HTML element or its id
    style: 'https://demotiles.maplibre.org/style.json', // any valid style URL
    center: [0, 0],                // [lng, lat]
    zoom: 2,
    // any other Map options you need …
  });

  // -----------------------------------------------------------------------
  // Example: listen to a data event – note the new event types
  // -----------------------------------------------------------------------
  map.on('data', (e: maplibregl.MapSourceDataEvent | maplibregl.MapStyleDataEvent) => {
    if ('sourceId' in e) {
      console.log('Source data event', e.sourceId, e.sourceDataType);
    } else {
      console.log('Style data event');
    }
  });

  // -----------------------------------------------------------------------
  // Public camera API (instead of the removed map.transform)
  // -----------------------------------------------------------------------
  map.on('load', () => {
    console.log('Zoom:', map.getZoom());
    console.log('Center:', map.getCenter().toArray());
    console.log('Pitch:', map.getPitch());
    console.log('Bearing:', map.getBearing());
  });

  return map;
}
```

### How to use it

#### React (functional component)

```tsx
// src/App.tsx
import { useEffect, useRef } from 'react';
import { initMap } from './map';

export default function App() {
  const mapContainer = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (mapContainer.current) {
      initMap(mapContainer.current);
    }
  }, []);

  return <div ref={mapContainer} style={{ width: '100vw', height: '100vh' }} />;
}
```

#### Vanilla (plain HTML + TS)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>MapLibre + Vite</title>
  <style>
    #map { width: 100vw; height: 100vh; }
  </style>
</head>
<body>
  <div id="map"></div>
  <script type="module">
    import { initMap } from './src/map.ts';
    initMap('#map');
  </script>
</body>
</html>
```

